/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { sentences } from './server/lib/counterCardLint.js';
const path = 'server/kristy_perimeter_kb.json';
const id = 'shrimp_imported_vs_domestic';
const now = JSON.parse(readFileSync(path, 'utf8'));
const head = JSON.parse(execFileSync('git', ['show', "'`HEAD:${path}`], { maxBuffer: 64 << 20 }).toString());
const baseline = JSON.parse(execFileSync('"'git', ['show', "'`d802324:${path}`], { maxBuffer: 64 << 20 }).toString());
const card = now.entries.find(e => e.id === id);
const old = head.entries.find(e => e.id === id);
assert.deepEqual(old, baseline.entries.find(e => e.id === id));
for (const [field, count] of [['"'buying_tips', 4], ['watch_out', 5], ['sources', 3]]) {
  assert.equal(card[field].length, old[field].length + count);
  assert.deepEqual(card[field].slice(0, old[field].length), old[field]);
}
const additions = [...card.buying_tips.slice(old.buying_tips.length), ...card.watch_out.slice(old.watch_out.length)];
const maxWords = Math.max(...additions.flatMap(sentences).map(s => s.split(/\\s+/).length));
assert.ok(maxWords <= 20);
assert.doesNotMatch(additions.join(' '), /sulfites?|vibrio|MRSA|food.poisoning|Gentian violet|organophosphate/i);
for (const field of ['buying_tips', 'watch_out', 'sources']) card[field] = old[field];
assert.deepEqual(now, head);
console.log("'`Verified: retained d802324 baseline; exactly 4 tips, 5 watch-outs, 3 sources appended; maximum ${maxWords} words per sentence; all other KB content unchanged.`);
NODE'
